function digest(input) {
  const plant = String(input.plantName || input.plant_name || 'your plant').trim() || 'your plant';
  const to = String(input.email || input.to || '').trim();
  const deck = Array.isArray(input.deck) ? input.deck : [];
  const rows = [];
  for (const card of deck) {
    const id = card.habitId || card.habit_id || '';
    const name = card.name || (id ? id.replace(/-/g, ' ') : '');
    if (!name) continue;
    rows.push({ slot: card.slot || 'mission', name, done: Boolean(card.done) });
  }
  if (!rows.length) rows.push({ slot: 'mission', name: 'Drink water, move a little, and protect your sleep tonight', done: false });
  const listHtml = rows.map((r) => `<li style="margin:0 0 10px;padding:10px 12px;background:#24361c;border-radius:12px;color:#f4f7f0"><div style="font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#bef264">${r.slot}</div><div style="font-size:16px;font-weight:700;margin-top:4px">${r.name}</div></li>`).join('');
  const listText = rows.map((r) => `- [${r.slot}] ${r.name}${r.done ? ' ✓' : ''}`).join('\n');
  return {
    to,
    subject: `Today's healthy-life missions for ${plant}`,
    html: `<div style="font-family:Georgia,serif;background:#0c1209;padding:24px;color:#f4f7f0"><p style="letter-spacing:.2em;text-transform:uppercase;font-size:11px;color:#c9ddb8">Virtual Plant</p><h1 style="font-size:26px;margin:8px 0 12px">Feed ${plant} with today's real life.</h1><p>Complete these on <a href="https://virtualplanty.netlify.app" style="color:#bef264">virtualplanty.netlify.app</a> to feed the tree.</p><ol style="padding:0;list-style:none;margin:20px 0">${listHtml}</ol></div>`,
    text: `Virtual Plant — today's missions for ${plant}\n\n${listText}\n\nOpen: https://virtualplanty.netlify.app`,
  };
}
const src = $json.body || $json;
const built = digest(src);
return [{ json: built }];
